	@Test
	void reindexWithMapGrowthPreservesEveryStatement() throws Exception {
		StoreProperties properties = new StoreProperties(dir);
		int count = 30000;
		try (TripleStore store = new TripleStore(dir, properties,
				new LmdbStoreConfig("spoc").setTripleDBSize(512 * 1024), null)) {
			store.startTransaction();
			for (int i = 0; i < count; i++) {
				long predicate = 1 + ((i * 6364136223846793005L) & Long.MAX_VALUE);
				store.storeTriple(1000 + i, predicate, 3000 + i, 0, true);
			}
			store.commit();
			properties.save();
		}
		properties = new StoreProperties(dir);
		properties.load();
		try (TripleStore store = new TripleStore(dir, properties,
				new LmdbStoreConfig("sp,op,cs,psoc,posc,scpo").setTripleDBSize(512 * 1024), null)) {
			// The changed full and partial indexes are built by the background rebuild, which grows the map.
			store.startBackgroundIndexRebuild();
			assertTrue(store.awaitIndexRebuild(60, TimeUnit.SECONDS), store.indexRebuildStatus());
			assertEquals(count, rows(store, -1, -1, -1, -1, true).size());
			assertEquals(count, pairs(store, "sp", true));
			assertEquals(count, pairs(store, "op", true));
			assertEquals(count, pairs(store, "cs", true));
			assertEquals(1, rows(store, 1000 + count - 1, -1, -1, -1, true).size());
			assertEquals(1, rows(store, -1, -1, 3000 + count - 1, -1, true).size());
		}
	}

