	@Test
	void addingPartialIndexIsDeferredToTheBackgroundBuild() throws Exception {
		try (TripleStore store = open("spoc")) {
			store.startTransaction();
			store.storeTriple(11, 22, 33, 0, true);
			store.storeTriple(11, 22, 44, 0, true);
			store.storeTriple(12, 23, 34, 5, false);
			store.commit();
		}
		try (TripleStore store = openWithoutRebuild("sp,spoc")) {
			assertFalse(isActivePartial(store, "sp"), "an unbuilt partial index must not be active");
			assertEquals(Set.of("[11, 22, 33, 0]", "[11, 22, 44, 0]"), rows(store, 11, -1, -1, -1, true));
			// Writes while the build is pending must reach the new partial index.
			store.startTransaction();
			store.storeTriple(13, 24, 35, 0, true);
			store.commit();
			remove(store, 12, 23, 34, 5, false);

			store.startBackgroundIndexRebuild();
			assertTrue(store.awaitIndexRebuild(30, TimeUnit.SECONDS), store.indexRebuildStatus());
			assertTrue(isActivePartial(store, "sp"), "the published generation must contain the new partial index");
			assertEquals(2, pairs(store, "sp", true));
			assertEquals(0, pairs(store, "sp", false));
		}
		try (TripleStore store = openWithoutRebuild("sp,spoc")) {
			assertTrue(isActivePartial(store, "sp"), "the published partial index must be committed in the manifest");
			assertEquals(2, pairs(store, "sp", true));
		}
	}

	@Test
	void removingPartialIndexKeepsItUntilTheBackgroundBuildRetiresIt() throws Exception {
		try (TripleStore store = open("sp,spoc")) {
			store.startTransaction();
			store.storeTriple(11, 22, 33, 0, true);
			store.commit();
			assertEquals(1, pairs(store, "sp", true));
		}
		try (TripleStore store = openWithoutRebuild("spoc")) {
			assertTrue(isActivePartial(store, "sp"), "the committed generation keeps its partial index until cutover");
			assertEquals(1, pairs(store, "sp", true));

			store.startBackgroundIndexRebuild();
			assertTrue(store.awaitIndexRebuild(30, TimeUnit.SECONDS), store.indexRebuildStatus());
			assertFalse(isActivePartial(store, "sp"));
			assertEquals(0, pairs(store, "sp", true), "a retired partial index is emptied after cutover");
			assertEquals(Set.of("[11, 22, 33, 0]"), rows(store, 11, -1, -1, -1, true));
		}
	}

